-- Daily challenges for 2026-10-10: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-10

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('easing-sunday-night-dread', 'Easing Sunday Night Dread', 'For anyone whose weekend ends with a knot in the stomach about the week ahead. Each day is one small way to prepare gently, keep the last evening of the weekend your own, and start the week with less dread.', 'Stress', 365, array['Stress', 'Work', 'Worry']::text[], 1, '2026-10-10T17:00:00+00:00'::timestamptz),
  ('showing-up-for-a-friend', 'Showing Up for a Friend', 'For anyone who wants to be there for the people they care about, especially when life gets hard for them. Each day is one small, practical way to check in, listen, help, or celebrate, so friends feel less alone.', 'Connection', 365, array['Relationships', 'Communication']::text[], 1, '2026-10-10T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('easing-sunday-night-dread', 'showing-up-for-a-friend');

